import React, {useEffect, useMemo, useState} from 'react';
import {Home as HomeIcon,Dumbbell,ChevronRight,Play,CheckCircle2,ArrowLeft,Clock3,History,User,Pause,RotateCcw,Timer,TrendingUp,Save,Search,Filter,Info} from 'lucide-react';
import {programs} from './data/programs';
import {globalPrograms} from './data/globalPrograms';
import {exercises,exerciseGroups} from './data/exercises';
import {buildPersonalPlan} from './data/personalPlan';
import {useWorkoutStorage} from './hooks/useWorkoutStorage';
import {getProgressionSuggestion} from './utils/progression';
import {buildAthleteAnalysis} from './utils/athleteAnalysis';
import {buildCoachPlan,preWorkoutQuestions,buildPreWorkoutAdjustment,adjustNextSet} from './utils/coach';
import {buildWeeklyReport} from './utils/weeklyReport';
import {buildReportTimeline} from './utils/reportTimeline';
import CloudStatus from './components/CloudStatus';
import Exercise3DDemo from './components/Exercise3DDemo';

function Header({title,onBack}){return <header className="header">{onBack?<button className="iconBtn" onClick={onBack}><ArrowLeft size={22}/></button>:<div className="logoMark">AT</div>}<h1>{title}</h1><div style={{width:40}}/></header>}

function Home({go,history,profile,cloud}){const last=history[0];return <><Header title="App Treino"/><main className="page"><CloudStatus cloud={cloud}/><section className="hero"><span>SEU TREINO DE HOJE</span><h2>Olá, {profile.name}!</h2><p>Pronto para evoluir? Escolha um programa e registre seu progresso.</p><button className="primary" onClick={()=>go('programs')}>Ver programas <ChevronRight size={20}/></button><button className="secondary heroSecondary" onClick={()=>go('globalPrograms')}><TrendingUp size={18}/> Explorar treinos globais</button><button className="secondary heroSecondary" onClick={()=>go('personalPlan')}><Dumbbell size={18}/> Criar meu plano automático</button><button className="secondary heroSecondary" onClick={()=>go('coach')}><TrendingUp size={18}/> Abrir Personal Trainer</button></section><section><div className="sectionTitle"><h3>Acesso rápido</h3></div><div className="quickGrid"><button onClick={()=>go('programs')}><Dumbbell/><b>Programas</b><small>Escolha seu objetivo</small></button><button onClick={()=>go('library')}><Search/><b>Exercícios</b><small>Consultar biblioteca</small></button><button onClick={()=>go('custom')}><Save/><b>Meus treinos</b><small>Criar treino personalizado</small></button><button onClick={()=>go('history')}><History/><b>Histórico</b><small>{history.length} treino(s) salvo(s)</small></button><button onClick={()=>go('analysis')}><TrendingUp/><b>Análise</b><small>Veja sua evolução</small></button><button onClick={()=>go('weeklyReport')}><Save/><b>Relatório</b><small>Resumo semanal</small></button></div></section>{last&&<section className="lastWorkout"><b>Último treino</b><span>{last.programName} • {new Date(last.date).toLocaleDateString('pt-BR')}</span></section>}</main><BottomNav active="home" go={go}/></>}

function Library({go}){const [query,setQuery]=useState('');const [group,setGroup]=useState('Todos');const filtered=useMemo(()=>exercises.filter(e=>(group==='Todos'||e.group===group)&&e.name.toLowerCase().includes(query.toLowerCase())),[query,group]);return <><Header title="Exercícios" onBack={()=>go('home')}/><main className="page"><div className="searchBox"><Search size={19}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar exercício por nome"/></div><div className="filterTitle"><h3>Grupo muscular</h3><Filter size={18}/></div><div className="chips">{exerciseGroups.map(g=><button key={g} className={group===g?'chip active':'chip'} onClick={()=>setGroup(g)}>{g}</button>)}</div><p className="muted">{filtered.length} exercício(s) encontrado(s)</p><div className="cards">{filtered.map(e=><button className="programCard" key={e.id} onClick={()=>go('exercise',e)}><div className="programIcon"><Dumbbell size={22}/></div><div className="cardText"><h3>{e.name}</h3><span>{e.group} • {e.level}</span><p>{e.equipment}</p></div><ChevronRight/></button>)}</div>{filtered.length===0&&<div className="empty"><Search size={34}/><b>Nenhum exercício encontrado</b><span>Tente outro nome ou grupo muscular.</span></div>}</main><BottomNav active="library" go={go}/></>}

function ExerciseAnimation({exercise}){
  const [playing,setPlaying]=useState(true);
  const [showSteps,setShowSteps]=useState(true);
  const gif=exercise.gif||exercise.gifUrl||exercise.animationUrl||'';
  return <section className="exerciseVisual">
    <div className="exerciseVisualHead">
      <div><span>DEMONSTRAÇÃO</span><h3>{exercise.name}</h3></div>
      <button className={playing?'demoToggle active':'demoToggle'} onClick={()=>setPlaying(v=>!v)}>{playing?'Pausar':'Reproduzir'} <span>{playing?'Ⅱ':'▶'}</span></button>
    </div>
    <div className="exerciseVisualStage">
      {gif
        ? <img className="exerciseGif" src={gif} alt={'Demonstração de '+exercise.name}/>
        : <div className={playing?'exercise3DFallback':'exercise3DFallback paused'}><Exercise3DDemo exercise={exercise} playing={playing}/></div>}
    </div>
    <div className="exerciseVisualControls">
      <button className={showSteps?'visualTab active':'visualTab'} onClick={()=>setShowSteps(v=>!v)}>{showSteps?'Ocultar execução':'Ver execução'}</button>
      <span>Movimento completo • visual de referência</span>
    </div>
    {showSteps&&<div className="exerciseStepsClean">{exercise.instructions.slice(0,3).map((step,i)=><div key={i}><b>{i+1}</b><span>{step}</span></div>)}</div>}
  </section>
}
function ExerciseDetails({exercise,go}){return <><Header title="Exercício" onBack={()=>go('library')}/><main className="page">
  <section className="exerciseHero cleanExerciseHero"><div><span>{exercise.group}</span><h2>{exercise.name}</h2><p>{exercise.description}</p></div><div className="exerciseMeta"><b>{exercise.level}</b><b>{exercise.equipment}</b></div></section>
  <ExerciseAnimation exercise={exercise}/>
  <section className="detailSection compactDetail"><h3>Como executar</h3><ol>{exercise.instructions.map((step,i)=><li key={i}>{step}</li>)}</ol></section>
  <section className="detailSection tip"><Info size={19}/><div><b>Dica</b><p>{exercise.tips}</p></div></section>
  <button className="primary full" onClick={()=>go('programs')}>Ver programas</button>
  <p className="exerciseSafety">A demonstração é uma referência visual. Ajuste carga, amplitude e execução ao seu nível e, se tiver dor ou dúvida técnica, procure orientação de um profissional qualificado.</p>
</main></>}
function CustomWorkouts({go,customWorkouts}){return <><Header title="Meus treinos" onBack={()=>go('home')}/><main className="page"><button className="primary full createWorkoutBtn" onClick={()=>go('builder')}><Dumbbell/> Criar novo treino</button><p className="muted">Seus treinos personalizados ficam salvos no aparelho e, com Firebase configurado, também na nuvem.</p><div className="cards">{customWorkouts.length===0?<div className="empty"><Dumbbell size={34}/><b>Nenhum treino personalizado</b><span>Monte seu primeiro treino escolhendo os exercícios.</span></div>:customWorkouts.map(w=><button className="programCard" key={w.id} onClick={()=>go('customDetails',w)}><div className="programIcon"><Dumbbell size={22}/></div><div className="cardText"><h3>{w.name}</h3><span>{w.exercises.length} exercícios • {w.level||'Personalizado'}</span><p>{w.exercises.reduce((s,e)=>s+e.sets,0)} séries</p></div><ChevronRight/></button>)}</div></main><BottomNav active="custom" go={go}/></>}

function Builder({go,saveCustomWorkout}){
  const [name,setName]=useState('Meu treino');
  const [selected,setSelected]=useState([]);
  const [query,setQuery]=useState('');
  const filtered=exercises.filter(e=>e.name.toLowerCase().includes(query.toLowerCase()));
  const toggle=(exercise)=>setSelected(prev=>prev.some(x=>x.id===exercise.id)
    ? prev.filter(x=>x.id!==exercise.id)
    : [...prev,{...exercise,sets:3,reps:10,rest:60}]);
  const update=(id,key,value)=>setSelected(prev=>prev.map(e=>e.id===id
    ? {...e,[key]:Math.max(1,Number(value)||1)}
    : e));
  const save=async()=>{
    if(!name.trim()||!selected.length)return;
    const workout={
      id:`custom-${Date.now()}`,
      name:name.trim(),
      level:'Personalizado',
      duration:`${Math.max(10,Math.round(selected.length*7))} min`,
      description:'Treino criado por você.',
      exercises:selected,
      createdAt:new Date().toISOString()
    };
    const saved=await saveCustomWorkout(workout);
    go('customDetails',saved);
  };
  return <>
    <Header title="Criar treino" onBack={()=>go('custom')}/>
    <main className="page">
      <label>Nome do treino
        <input value={name} onChange={e=>setName(e.target.value)} placeholder="Ex.: Treino A"/>
      </label>
      <div className="searchBox">
        <Search size={19}/>
        <input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Adicionar exercício"/>
      </div>
      <h3>Exercícios selecionados ({selected.length})</h3>
      <div className="builderList">
        {selected.map((e,i)=>
          <div className="builderCard" key={e.id}>
            <div className="builderTop">
              <b>{i+1}. {e.name}</b>
              <button className="removeBtn" onClick={()=>toggle(e)}>Remover</button>
            </div>
            <div className="formGrid">
              <label>Séries<input inputMode="numeric" type="number" min="1" value={e.sets} onChange={x=>update(e.id,'sets',x.target.value)}/></label>
              <label>Reps<input inputMode="numeric" type="number" min="1" value={e.reps} onChange={x=>update(e.id,'reps',x.target.value)}/></label>
            </div>
            <label>Descanso (segundos)<input inputMode="numeric" type="number" min="0" value={e.rest} onChange={x=>update(e.id,'rest',x.target.value)}/></label>
          </div>
        )}
      </div>
      {selected.length===0&&<p className="muted">Selecione exercícios abaixo para montar seu treino.</p>}
      <div className="cards builderChoices">
        {filtered.map(e=>
          <button className={selected.some(x=>x.id===e.id)?'programCard selectedExercise':'programCard'} key={e.id} onClick={()=>toggle(e)}>
            <div className="programIcon"><Dumbbell size={20}/></div>
            <div className="cardText"><h3>{e.name}</h3><span>{e.group} • {e.equipment}</span></div>
            <b>{selected.some(x=>x.id===e.id)?'✓':'+'}</b>
          </button>
        )}
      </div>
      <button className="primary full" disabled={!name.trim()||!selected.length} onClick={save}>
        <Save/> Salvar meu treino
      </button>
    </main>
  </>;
}

function CustomDetails({program,go}){
  return <>
    <Header title={program.name} onBack={()=>go('custom')}/>
    <main className="page">
      <section className="summary">
        <span>PERSONALIZADO</span>
        <h2>{program.description}</h2>
        <b>{program.exercises.length} exercícios</b>
      </section>
      <div className="exerciseList">
        {program.exercises.map((e,i)=>
          <div className="exerciseRow" key={e.id}>
            <strong>{i+1}</strong>
            <div><b>{e.name}</b><small>{e.group} • {e.sets} séries × {e.reps} • {e.rest}s descanso</small></div>
          </div>
        )}
      </div>
      <button className="primary full" onClick={()=>go('workout',program)}>
        <Play size={20}/> Iniciar treino
      </button>
    </main>
  </>;
}

function PersonalPlan({go,profile,setProfile}){const [step,setStep]=useState(0);const [draft,setDraft]=useState({goal:profile.goal||'Hipertrofia',imc:profile.imc||'',age:profile.age||'',level:profile.level||'Iniciante',days:profile.days||3,equipment:profile.equipment||['Academia']});const toggleEq=(item)=>setDraft(d=>({...d,equipment:d.equipment.includes(item)?d.equipment.filter(x=>x!==item):[...d.equipment,item]}));const plan=step===5?buildPersonalPlan(draft):null;const next=()=>setStep(s=>s+1);const save=()=>{setProfile({...profile,...draft,imc:Number(draft.imc)||'',age:Number(draft.age)||'',days:Number(draft.days)||3});go('personalDetails',plan)};const labels=['Objetivo','IMC','Idade','Nível','Dias','Equipamentos'];return <><Header title="Montar meu plano" onBack={()=>go('home')}/><main className="page"><div className="wizardProgress">{labels.map((x,i)=><span className={i<=step?'done':''} key={x}>{i+1}</span>)}</div>{step===0&&<section className="wizardCard"><h2>Qual é seu objetivo?</h2><div className="choiceGrid">{['Hipertrofia','Força','Emagrecimento','Condicionamento'].map(x=><button className={draft.goal===x?'choice active':'choice'} onClick={()=>setDraft({...draft,goal:x})} key={x}>{x}</button>)}</div></section>}{step===1&&<section className="wizardCard"><h2>Qual é seu IMC?</h2><p className="muted">Se já informou altura e peso no perfil, use o valor calculado. Caso contrário, digite o IMC.</p><input type="number" step="0.1" value={draft.imc} onChange={e=>setDraft({...draft,imc:e.target.value})} placeholder="Ex.: 24,5"/></section>}{step===2&&<section className="wizardCard"><h2>Qual sua idade?</h2><input type="number" min="16" max="100" value={draft.age} onChange={e=>setDraft({...draft,age:e.target.value})} placeholder="Ex.: 30"/></section>}{step===3&&<section className="wizardCard"><h2>Qual seu nível?</h2><div className="choiceGrid">{['Iniciante','Intermediário','Avançado'].map(x=><button className={draft.level===x?'choice active':'choice'} onClick={()=>setDraft({...draft,level:x})} key={x}>{x}</button>)}</div></section>}{step===4&&<section className="wizardCard"><h2>Quantos dias por semana?</h2><div className="choiceGrid">{[2,3,4,5,6].map(x=><button className={Number(draft.days)===x?'choice active':'choice'} onClick={()=>setDraft({...draft,days:x})} key={x}>{x} dias</button>)}</div></section>}{step===5&&<section className="wizardCard"><h2>Quais equipamentos você tem?</h2><div className="choiceGrid">{['Academia','Halteres','Barra','Cabos','Máquinas','Peso corporal'].map(x=><button className={draft.equipment.includes(x)?'choice active':'choice'} onClick={()=>toggleEq(x)} key={x}>{x}</button>)}</div></section>}<div className="wizardActions">{step>0&&<button className="secondary" onClick={()=>setStep(s=>s-1)}>Voltar</button>}{step<5?<button className="primary" onClick={next}>Continuar</button>:<button className="primary" onClick={save}>Gerar meu plano</button>}</div></main></>}

function PersonalDetails({go,plan,saveCustomWorkout}){const [saved,setSaved]=useState(false);if(!plan)return null;const startDay=(day)=>{const program={id:`personal-${Date.now()}-${day.day}`,name:`${plan.name} • ${day.title}`,level:plan.level,duration:day.duration,description:'Sessão do plano personalizado.',exercises:day.exercises};go('workout',program)};const savePlan=async()=>{const exercises=plan.week.flatMap(day=>day.exercises.map(e=>({...e,day:day.day,dayTitle:day.title})));const savedPlan=await saveCustomWorkout({id:`personal-plan-${Date.now()}`,name:plan.name,level:plan.level,duration:`${plan.days} dias/semana`,description:plan.summary,goal:plan.goal,days:plan.days,exercises,createdAt:new Date().toISOString()});setSaved(true);go('customDetails',savedPlan)};return <><Header title="Seu plano personalizado" onBack={()=>go('personalPlan')}/><main className="page"><section className="personalHero"><span>PLANO GERADO</span><h2>{plan.name}</h2><p>{plan.summary}</p><div className="planStats"><b>{plan.days} dias</b><b>{plan.level}</b><b>{plan.goal}</b></div></section><div className="weeklyPlan">{plan.week.map(day=><article className="dayCard" key={day.day}><div className="dayHead"><div><span>Dia {day.day}</span><h3>{day.title}</h3></div><small>{day.duration}</small></div>{day.exercises.map((e,i)=><div className="planExercise" key={e.id+'-'+i}><div><b>{e.name}</b><small>{e.muscle} • {e.sets} séries × {e.reps}</small></div><strong>{e.rest}s</strong></div>)}<button className="secondary full" onClick={()=>startDay(day)}><Play size={18}/> Iniciar {day.title}</button></article>)}</div><div className="wizardActions"><button className="secondary" onClick={()=>go('personalPlan')}>Ajustar plano</button><button className="primary" disabled={saved} onClick={savePlan}><Save size={18}/> {saved?'Plano salvo':'Salvar plano completo'}</button></div><p className="muted planDisclaimer">Plano automático para adultos saudáveis. O IMC é apenas uma variável de triagem; ele não determina sozinho a escolha de exercícios. Em caso de dor, condição médica, lesão ou dúvida sobre segurança, procure um profissional qualificado.</p></main></>}
function GlobalPrograms({go}){return <><Header title="Treinos globais" onBack={()=>go('home')}/><main className="page"><section className="globalIntro"><span>CURADORIA INTERNACIONAL</span><h2>Treinos baseados em princípios atuais</h2><p>Uma seleção de estruturas de treino inspiradas em recomendações recentes e práticas amplamente utilizadas. O app não classifica um treino como universalmente melhor.</p></section><div className="cards">{globalPrograms.map(p=><button className="programCard" key={p.id} onClick={()=>go('globalDetails',p)}><div className="programIcon"><Dumbbell size={24}/></div><div className="cardText"><h3>{p.name}</h3><span>{p.goal} • {p.frequency}</span><p>{p.source}</p></div><ChevronRight/></button>)}</div><div className="sourceNote"><Info size={18}/><span>Referência principal: ACSM 2026. Ajuste o treino ao seu objetivo, experiência e disponibilidade.</span></div></main><BottomNav active="programs" go={go}/></>}

function GlobalDetails({program,go}){return <><Header title={program.name} onBack={()=>go('globalPrograms')}/><main className="page"><section className="summary"><span>{program.goal}</span><h2>{program.description}</h2><b>{program.level} • {program.frequency}</b><small className="sourceLabel">{program.source}</small></section><h3>Estrutura</h3><div className="exerciseList">{program.exercises.map((e,i)=><div className="exerciseRow" key={e.id}><strong>{i+1}</strong><div><b>{e.name}</b><small>{e.muscle} • {e.sets} séries × {e.reps} • {e.rest}s</small></div></div>)}</div><button className="primary full" onClick={()=>go('workout',program)}><Play size={20}/> Iniciar treino</button></main></>}

function Programs({go}){return <><Header title="Programas" onBack={()=>go('home')}/><main className="page"><p className="muted">Selecione um programa para ver os exercícios.</p><div className="cards">{programs.map(p=><button className="programCard" key={p.id} onClick={()=>go('details',p)}><div className="programIcon"><Dumbbell size={24}/></div><div className="cardText"><h3>{p.name}</h3><span>{p.level} • {p.duration}</span><p>{p.description}</p></div><ChevronRight/></button>)}</div></main><BottomNav active="programs" go={go}/></>}

function Details({program,go}){return <><Header title={program.name} onBack={()=>go('programs')}/><main className="page"><section className="summary"><span>{program.level}</span><h2>{program.description}</h2><b>{program.exercises.length} exercícios • {program.duration}</b></section><h3>Exercícios</h3><div className="exerciseList">{program.exercises.map((e,i)=><div className="exerciseRow" key={e.id}><strong>{i+1}</strong><div><b>{e.name}</b><small>{e.muscle} • {e.sets} séries × {e.reps}</small></div></div>)}</div><button className="primary full" onClick={()=>go('workout',program)}><Play size={20}/> Começar treino</button></main></>}

function RestTimer({seconds}){const [remaining,setRemaining]=useState(seconds);const [running,setRunning]=useState(false);useEffect(()=>{if(!running)return;const id=setInterval(()=>setRemaining(v=>{if(v<=1){setRunning(false);return 0}return v-1}),1000);return()=>clearInterval(id)},[running]);useEffect(()=>{setRemaining(seconds);setRunning(false)},[seconds]);return <div className="timerBox"><div><Timer size={18}/><b>{String(Math.floor(remaining/60)).padStart(2,'0')}:{String(remaining%60).padStart(2,'0')}</b></div><button onClick={()=>setRunning(v=>!v)}>{running?<Pause size={17}/>:<Play size={17}/>}</button><button onClick={()=>{setRunning(false);setRemaining(seconds)}}><RotateCcw size={17}/></button></div>}

function Workout({program,go,saveWorkout,history}){const [index,setIndex]=useState(0);const [series,setSeries]=useState({});const [current,setCurrent]=useState({weight:'',reps:'',rpe:'7'});const [lastAdjustment,setLastAdjustment]=useState(null);const ex=program.exercises[index];const loggedSets=series[ex.id]||[];const completed=loggedSets.length;const last=index===program.exercises.length-1;const suggestion=getProgressionSuggestion(history,ex);const baseRest=Number(ex.rest)||90;const progress=Math.round(((index+completed/ex.sets)/program.exercises.length)*100);const finish=()=>{saveWorkout({id:Date.now(),date:new Date().toISOString(),programId:program.id,programName:program.name,minutes:parseInt(program.duration)||0,exercises:Object.entries(series).map(([exerciseId,details])=>({exerciseId,sets:details.length,details}))});go('done',program)};const addSet=()=>{if(completed>=ex.sets)return;const reps=Number(current.reps)||Number(ex.reps)||0;const weight=Number(current.weight)||0;const rpe=Math.min(10,Math.max(1,Number(current.rpe)||7));const next=adjustNextSet({weight,reps,targetReps:Number(ex.reps)||10,rpe,rest:lastAdjustment?.rest||baseRest});const entry={weight,reps,rpe,rest:next.rest,adjustment:next};setSeries(s=>({...s,[ex.id]:[...(s[ex.id]||[]),entry]}));setLastAdjustment(next);setCurrent({weight:next.weight?String(next.weight):current.weight,reps:next.reps?String(next.reps):String(ex.reps||''),rpe:'7'})};const moveNext=()=>{setLastAdjustment(null);setIndex(index+1)};const back=()=>go(String(program.id).startsWith('custom-')||String(program.id).startsWith('personal-plan-')?'customDetails':'details',program);return <><Header title="Treino" onBack={back}/><main className="page"><div className="progressLabel"><span>Exercício {index+1} de {program.exercises.length}</span><b>{Math.min(progress,100)}%</b></div><div className="progress"><div style={{width:Math.min(progress,100)+'%'}}/></div><section className="workoutCard"><span>{ex.muscle||ex.group}</span><h2>{ex.name}</h2><div className="stats"><div><b>{ex.sets}</b><small>Séries</small></div><div><b>{ex.reps}</b><small>Meta reps</small></div><div><b>{lastAdjustment?.rest||ex.rest}s</b><small>Descanso</small></div></div></section>{suggestion&&!lastAdjustment&&<div className="progressionHint"><TrendingUp size={18}/><div><b>Próxima sugestão</b><span>{suggestion.label}</span><small>{suggestion.weight?'Carga sugerida: '+suggestion.weight+' kg • ':''}Meta: {suggestion.reps} reps</small></div></div>}{lastAdjustment&&<div className={lastAdjustment.action==='reduzir'?'coachSetAdjust down':'coachSetAdjust'}><div className="coachSetAdjustHead"><TrendingUp size={18}/><div><b>Coach ajustou a próxima série</b><span>{lastAdjustment.reason}</span></div></div><div className="coachSetMetrics"><div><b>{lastAdjustment.weight||'—'}</b><small>kg</small></div><div><b>{lastAdjustment.reps}</b><small>reps</small></div><div><b>{lastAdjustment.rest}s</b><small>descanso</small></div></div></div>}<div className="setPanel"><h3>Registrar série {completed+1} de {ex.sets}</h3><p className="setCoachPrompt">Faça a série com a carga indicada. <b>Depois da série, informe o RPE</b> e o Coach ajustará automaticamente a próxima.</p><div className="formGrid"><label>Carga (kg)<input inputMode="decimal" value={current.weight} onChange={e=>setCurrent({...current,weight:e.target.value})} placeholder={suggestion.weight?String(suggestion.weight):'Ex.: 20'}/></label><label>Reps<input inputMode="numeric" value={current.reps} onChange={e=>setCurrent({...current,reps:e.target.value})} placeholder={String(lastAdjustment?.reps||suggestion.reps||ex.reps)}/></label></div><label>RPE após a série (1–10)<select value={current.rpe} onChange={e=>setCurrent({...current,rpe:e.target.value})}>{Array.from({length:10},(_,i)=><option key={i+1} value={i+1}>{i+1} — {i<3?'Muito fácil':i<5?'Fácil':i<7?'Moderada':i<9?'Difícil':'Muito difícil'}</option>)}</select></label><button className="primary full" disabled={completed>=ex.sets} onClick={addSet}><Save size={18}/> Registrar série e ajustar próxima</button><div className="setDots">{Array.from({length:ex.sets},(_,i)=><span className={i<completed?'done':''} key={i}>{i+1}</span>)}</div></div>{completed>0&&<div className="setHistory"><div className="reportTitle"><h3>Séries registradas</h3><span>{completed}/{ex.sets}</span></div>{loggedSets.map((s,i)=><div className="setHistoryRow" key={i}><span>Série {i+1}</span><b>{s.weight||0} kg × {s.reps} reps</b><strong>RPE {s.rpe}</strong></div>)}</div>}<RestTimer seconds={lastAdjustment?.rest||ex.rest}/><button className="secondary full" disabled={completed<ex.sets} onClick={()=>last?finish():moveNext()}>{last?'Finalizar treino':'Próximo exercício'} <ChevronRight/></button></main></>}
function Done({program,go}){return <main className="page done"><div className="doneIcon"><CheckCircle2 size={58}/></div><h1>Treino concluído!</h1><p>Você terminou o programa <b>{program.name}</b>.</p><div className="result"><div><b>{program.exercises.length}</b><span>Exercícios</span></div><div><b>{program.duration}</b><span>Duração</span></div></div><button className="primary full" onClick={()=>go('home')}>Voltar para Home</button><button className="secondary full" onClick={()=>go('history')}>Ver histórico</button></main>}

function HistoryScreen({history,go}){return <><Header title="Histórico" onBack={()=>go('home')}/><main className="page"><section className="metricGrid"><div><b>{history.length}</b><span>Treinos</span></div><div><b>{history.reduce((s,h)=>s+h.minutes,0)}</b><span>Minutos</span></div></section><div className="cards">{history.length===0?<div className="empty"><History size={36}/><b>Nenhum treino registrado</b><span>Conclua seu primeiro treino para ver aqui.</span></div>:history.map(h=><div className="historyCard" key={h.id}><div><b>{h.programName}</b><span>{new Date(h.date).toLocaleString('pt-BR')}</span></div><strong>{h.minutes} min</strong></div>)}</div><button className="secondary full" onClick={()=>go('evolution')}><TrendingUp/> Ver evolução</button></main></>}

function Evolution({history,go}){const rows=history.flatMap(h=>(h.exercises||[]).map(e=>{const d=e.details||[];const max=Math.max(0,...d.map(x=>Number(x.weight)||0));const avgRpe=d.length?d.reduce((s,x)=>s+(Number(x.rpe)||7),0)/d.length:0;const reps=d.length?d.reduce((s,x)=>s+(Number(x.reps)||0),0)/d.length:0;return {...e,date:h.date,programName:h.programName,maxWeight:max,avgRpe:Number(avgRpe.toFixed(1)),avgReps:Number(reps.toFixed(1))}}));const grouped={};rows.forEach(r=>{if(!grouped[r.exerciseId])grouped[r.exerciseId]=[];grouped[r.exerciseId].push(r)});const items=Object.entries(grouped).map(([id,list])=>{const ordered=[...list].sort((a,b)=>new Date(a.date)-new Date(b.date));const latest=ordered[ordered.length-1];const firstWeight=ordered.find(x=>x.maxWeight>0)?.maxWeight||0;const bestWeight=Math.max(...ordered.map(x=>x.maxWeight),0);const name=exercises.find(x=>x.id===id)?.name||id;const suggestion=getProgressionSuggestion(history,{id,reps:latest.avgReps||10,sets:latest.sets||3});return {id,name,ordered,latest,firstWeight,bestWeight,suggestion}});return <><Header title="Evolução" onBack={()=>go('history')}/><main className="page"><section className="metricGrid"><div><b>{history.length}</b><span>Treinos</span></div><div><b>{rows.reduce((s,e)=>s+(e.sets||0),0)}</b><span>Séries</span></div><div><b>{items.length}</b><span>Exercícios</span></div></section><section className="evolutionCard"><TrendingUp size={28}/><h2>Evolução por exercício</h2><p>Veja carga, repetições e dificuldade ao longo do tempo. O app também calcula a próxima sugestão com base no histórico.</p></section><div className="evolutionList">{items.length?items.map(e=>{const points=e.ordered.slice(-6);const maxPoint=Math.max(...points.map(x=>x.maxWeight),1);const change=e.firstWeight>0&&e.latest.maxWeight>0?Math.round(((e.latest.maxWeight-e.firstWeight)/e.firstWeight)*100):0;return <article className="evolutionItem" key={e.id}><div className="evolutionHeader"><div><b>{e.name}</b><small>{e.ordered.length} registro(s) • melhor carga {e.bestWeight} kg</small></div><span className={change>0?'trendUp':change<0?'trendDown':''}>{change>0?'+'+change+'%':change<0?change+'%':'—'}</span></div><div className="miniChart">{points.map((p,i)=><div className="chartPoint" key={p.date+i}><div className="barWrap"><div className="bar" style={{height:Math.max(8,Math.round((p.maxWeight/maxPoint)*100))+'%'}}/></div><small>{new Date(p.date).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})}</small><strong>{p.maxWeight||'—'}</strong></div>)}</div><div className="evolutionStats"><span>Último: <b>{e.latest.maxWeight||0} kg</b></span><span>Reps: <b>{e.latest.avgReps||0}</b></span><span>RPE: <b>{e.latest.avgRpe||0}</b></span></div><div className="progressionHint"><TrendingUp size={18}/><div><b>Próximo passo</b><span>{e.suggestion.label}</span><small>{e.suggestion.weight?'Carga sugerida: '+e.suggestion.weight+' kg • ':''}Meta: {e.suggestion.reps} reps</small></div></div></article>}):<div className="empty"><TrendingUp size={36}/><b>Ainda não há dados</b><span>Registre séries para começar sua evolução por exercício.</span></div>}</div></main></>}
function AthleteAnalysis({history,profile,go}){const analysis=useMemo(()=>buildAthleteAnalysis(history,profile),[history,profile]);const nameFor=id=>exercises.find(x=>x.id===id)?.name||id;return <><Header title="Análise do atleta" onBack={()=>go('home')}/><main className="page"><section className="athleteHero"><span>VISÃO GERAL</span><h2>{profile.name||'Atleta'}, veja seu momento</h2><p>Análise automática baseada nos treinos registrados, frequência, carga, repetições e dificuldade percebida.</p><div className="athleteScore"><div><b>{analysis.adherence}%</b><small>consistência semanal</small></div><div><b>{analysis.totalSets}</b><small>séries na semana</small></div><div><b>{analysis.avgRpe||'—'}</b><small>RPE médio</small></div></div></section><section className="analysisGrid"><div><span>Treinos</span><b>{analysis.week.length}/{analysis.targetDays}</b><small>últimos 7 dias</small></div><div><span>Volume</span><b>{analysis.volumeTrend>0?'+':''}{analysis.volumeTrend}%</b><small>vs. semana anterior</small></div></section><section className="analysisSection"><div className="analysisTitle"><h3>Pontos fortes</h3><TrendingUp size={19}/></div>{analysis.strong.length?analysis.strong.map(e=><div className="analysisRow" key={e.id}><div><b>{nameFor(e.id)}</b><small>{e.change>0?'+'+e.change+'% na última sessão':'evolução acumulada de '+e.longChange+'%'}</small></div><strong>{e.latest.maxWeight||0} kg</strong></div>):<div className="analysisEmpty">Registre mais sessões para identificar seus exercícios com melhor evolução.</div>}</section><section className="analysisSection"><div className="analysisTitle"><h3>Exercícios estagnados</h3><span className="statusTag">Atenção</span></div>{analysis.stalled.length?analysis.stalled.map(e=><div className="analysisRow" key={e.id}><div><b>{nameFor(e.id)}</b><small>{e.ordered.length} registros • evolução de {e.longChange}%</small></div><strong>{e.latest.maxWeight||0} kg</strong></div>):<div className="analysisEmpty">Nenhum exercício foi identificado como estagnado com os dados atuais.</div>}</section><section className="analysisSection"><div className="analysisTitle"><h3>Recomendações para a próxima semana</h3><Save size={19}/></div><div className="recommendationList">{analysis.recommendations.map((r,i)=><div className="recommendation" key={r.title}><strong>{i+1}</strong><div><b>{r.title}</b><p>{r.text}</p></div></div>)}</div></section><button className="primary full" onClick={()=>go('coach')}>Gerar próxima semana com Coach IA <ChevronRight size={18}/></button><button className="secondary full" onClick={()=>go('personalPlan')}>Ajustar meu plano</button><p className="muted analysisDisclaimer">A análise é um recurso de acompanhamento e não substitui avaliação profissional. As sugestões são baseadas somente nos dados registrados no aplicativo.</p></main><BottomNav active="home" go={go}/></>}
function CoachAI({history,profile,go,saveCustomWorkout}){const plan=useMemo(()=>buildCoachPlan(history,profile),[history,profile]);const [day,setDay]=useState(0);const current=plan.nextWeek[day]||plan.nextWeek[0];const [answers,setAnswers]=useState({sleep:3,energy:3,soreness:1,recovery:3,pain:0});const [assessment,setAssessment]=useState(null);const selectedSession=assessment?.session||current;const evaluate=()=>setAssessment(buildPreWorkoutAdjustment(answers,current));const save=async()=>{if(!selectedSession||assessment?.status==='pausar')return;const workout={id:'coach-prep-'+Date.now(),name:'Coach IA • '+selectedSession.title,level:plan.level,duration:selectedSession.duration,description:'Sessão ajustada pela avaliação pré-treino.',goal:plan.goal,exercises:selectedSession.exercises,createdAt:new Date().toISOString()};const saved=await saveCustomWorkout(workout);go('customDetails',saved)};const changeAnswer=(id,value)=>{setAnswers(a=>({...a,[id]:Number(value)}));setAssessment(null)};return <><Header title="Personal Trainer" onBack={()=>go('analysis')}/><main className="page"><section className="coachHero"><span>COACH IA • EVIDÊNCIA + DADOS</span><h2>Seu treino é ajustado ao seu momento.</h2><p>O motor combina objetivo, nível, frequência, histórico, RPE, volume, estagnação e agora sua prontidão antes de cada sessão.</p><div className="coachReadiness"><div><b>{plan.readinessScore}</b><small>prontidão do histórico</small></div><div><b>{plan.readiness}</b><small>estado recente</small></div></div></section><section className="coachSection preWorkout"><div className="reportTitle"><div><span className="coachEyebrow">ANTES DE COMEÇAR</span><h3>Avaliação pré-treino</h3></div><Info size={19}/></div><p className="muted">Responda em menos de 1 minuto. O Coach usa suas respostas para ajustar carga, volume e descanso da sessão de hoje.</p>{preWorkoutQuestions.map(q=><div className="preQuestion" key={q.id}><div className="preQuestionHead"><b>{q.title}</b><span>{q.id==='pain'?'segurança':'1–5'}</span></div><div className="preOptions">{q.options.map(o=><button key={o.value} className={answers[q.id]===o.value?'preOption active':'preOption'} onClick={()=>changeAnswer(q.id,o.value)}>{o.label}</button>)}</div><p className="preEffect">{q.options.find(o=>o.value===answers[q.id])?.effect}</p></div>)}<button className="primary full" onClick={evaluate}><TrendingUp size={18}/> Avaliar meu treino de hoje</button>{assessment&&<div className={assessment.status==='pausar'?'preResult danger':'preResult'}><div><span>{assessment.status==='pausar'?'SEGURANÇA':'PRONTIDÃO'}</span><b>{assessment.status==='pausar'?'—':assessment.score+'/100'}</b></div><div><strong>{assessment.title}</strong><p>{assessment.summary}</p></div><div className="adjustmentGrid"><span>Com base no sono: <b>{assessment.details?.sleep||'Sem ajuste'}</b></span><span>Energia: <b>{assessment.details?.energy||'Sem ajuste'}</b></span><span>Recuperação/dor muscular: <b>{assessment.details?.soreness||'Sem ajuste'}</b></span><span>Recuperação geral: <b>{assessment.details?.recovery||'Sem ajuste'}</b></span><span>Dor aguda: <b>{assessment.details?.pain||'Sem ajuste'}</b></span></div></div>}</section><section className="coachSection"><div className="reportTitle"><h3>Princípios usados pelo Coach</h3><TrendingUp size={19}/></div><div className="coachPrinciples">{(plan.methodology||[]).map((x,i)=><div key={x}><strong>{i+1}</strong><span>{x}</span></div>)}</div></section><section className="coachSection"><div className="reportTitle"><h3>Regras para o treino</h3><Info size={19}/></div><div className="coachRules"><p><b>Aquecimento:</b> {plan.sessionRules?.warmup}</p><p><b>Esforço:</b> {plan.sessionRules?.effort}</p><p><b>Progressão:</b> {plan.sessionRules?.progression}</p><p><b>Recuperação:</b> {plan.sessionRules?.recovery}</p></div></section><section className="coachSection"><div className="reportTitle"><h3>Próxima semana</h3><span>{plan.days} dias</span></div><div className="coachDayTabs">{plan.nextWeek.map((d,i)=><button key={d.day} className={day===i?'active':''} onClick={()=>{setDay(i);setAssessment(null)}}>Dia {i+1}</button>)}</div>{current&&<article className="coachDayCard"><div className="dayHead"><div><span>SESSÃO {current.day}</span><h3>{current.title}</h3></div><small>{selectedSession?.duration||current.duration}</small></div>{(selectedSession||current).exercises.map(e=><div className="coachExercise" key={e.id}><div><b>{e.name}</b><small>{e.sets} séries × {e.reps} reps{e.weight?' • '+e.weight+' kg':''}{e.rest?' • '+e.rest+'s':''}</small><p>{e.reason}</p></div><strong className={e.action==='aumentar'?'reportUp':e.action==='reduzir'?'reportDown':''}>{e.action}</strong></div>)}<button className="primary full" disabled={!assessment||assessment.status==='pausar'} onClick={()=>go('workout',{id:'coach-'+Date.now()+'-'+current.day,name:'Coach IA • '+selectedSession.title,level:plan.level,duration:selectedSession.duration,description:'Sessão ajustada pela avaliação pré-treino.',exercises:selectedSession.exercises})}><Play size={18}/> {assessment?.status==='pausar'?'Treino pausado':'Iniciar sessão ajustada'}</button><button className="secondary full" disabled={!assessment||assessment.status==='pausar'} onClick={save}><Save size={18}/> Salvar sessão ajustada</button>{!assessment&&<p className="muted coachGate">Faça a avaliação pré-treino acima para liberar o início da sessão.</p>}</article>}</section><section className="coachSection coachNotice"><b>Base científica</b><p>O desenho do Coach prioriza consistência, individualização, ajuste de carga e volume e progressão gradual. As respostas pré-treino servem para autorregulação e não são diagnóstico médico.</p></section><p className="muted analysisDisclaimer">Este Coach é um sistema de apoio ao treinamento, não um profissional humano. Não diagnostica lesões nem substitui avaliação médica ou de um profissional de educação física. Em caso de dor forte, aguda ou sintomas preocupantes, interrompa o exercício e procure avaliação apropriada.</p></main></>}
function WeeklyReport({history,profile,go}){const report=useMemo(()=>buildWeeklyReport(history,profile),[history,profile]);const fmt=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:0}).format(n||0);return <><Header title="Relatório semanal" onBack={()=>go('analysis')}/><main className="page"><section className="reportHero"><span>RELATÓRIO AUTOMÁTICO</span><h2>Seu resumo da semana</h2><p>Comparação entre o planejado e o realizado, com recomendações objetivas para o próximo ciclo.</p><div className="reportScore"><b>{report.adherence}%</b><small>aderência aos treinos</small></div></section><section className="reportGrid"><div><span>Planejado</span><b>{report.plannedSessions}</b><small>sessões</small></div><div><span>Realizado</span><b>{report.completedSessions}</b><small>sessões</small></div><div><span>Séries</span><b>{report.actualSets}/{report.plannedSets}</b><small>realizadas / planejadas</small></div><div><span>RPE médio</span><b>{report.avgRpe||'—'}</b><small>vs {report.prevRpe||'—'} anterior</small></div></section><section className="reportSection"><div className="reportTitle"><h3>Volume</h3><span className={report.volumeChange>0?'reportUp':report.volumeChange<0?'reportDown':''}>{report.previousVolume?((report.volumeChange>0?'+':'')+report.volumeChange+'%'):'Novo'}</span></div><div className="volumeCompare"><div><small>Semana atual</small><b>{fmt(report.volume)}</b><span>kg × reps</span></div><div><small>Semana anterior</small><b>{fmt(report.previousVolume)}</b><span>kg × reps</span></div></div></section><section className="reportSection"><div className="reportTitle"><h3>O que melhorou</h3><TrendingUp size={19}/></div>{report.improved.length?report.improved.map(x=><div className="reportRow" key={x.id}><div><b>{x.name}</b><small>Carga {x.oldMax||0} → {x.currentMax||0} kg • reps {x.oldReps||0} → {x.currentReps||0}</small></div><strong className="reportUp">{x.delta>0?'+'+x.delta+'%':'+'+x.repDelta+'%'} </strong></div>):<p className="reportMuted">Ainda não há comparação suficiente para apontar melhorias.</p>}</section><section className="reportSection"><div className="reportTitle"><h3>O que piorou</h3><Info size={19}/></div>{report.worsened.length?report.worsened.map(x=><div className="reportRow" key={x.id}><div><b>{x.name}</b><small>Carga {x.oldMax||0} → {x.currentMax||0} kg • reps {x.oldReps||0} → {x.currentReps||0}</small></div><strong className="reportDown">{x.delta+'%'}</strong></div>):<p className="reportMuted">Nenhum exercício apresentou queda clara nesta comparação.</p>}</section><section className="reportSection"><div className="reportTitle"><h3>Exercícios estagnados</h3><span className="statusTag">Atenção</span></div>{report.stalled.length?report.stalled.map(x=><div className="reportRow" key={x.id}><div><b>{x.name}</b><small>{x.ordered.length} registros • evolução acumulada {x.longChange}%</small></div><strong>{x.latest.maxWeight||0} kg</strong></div>):<p className="reportMuted">Nenhum exercício foi classificado como estagnado.</p>}</section><section className="reportSection"><div className="reportTitle"><h3>Recomendações para a próxima semana</h3><Save size={19}/></div><div className="recommendationList">{report.recommendations.map((r,i)=><div className="recommendation" key={r}><strong>{i+1}</strong><div><p>{r}</p></div></div>)}</div></section><button className="primary full" onClick={()=>go('coach')}><TrendingUp size={18}/> Gerar próxima semana com Coach IA</button><button className="secondary full" onClick={()=>go('reportTimeline')}><History size={18}/> Ver linha do tempo</button><p className="muted analysisDisclaimer">Relatório baseado exclusivamente nos dados registrados no aplicativo. Ele serve para acompanhamento e não substitui avaliação profissional.</p></main></>}
function ReportTimeline({history,profile,go}){const [range,setRange]=useState(12);const [exercise,setExercise]=useState('Todos');const data=useMemo(()=>buildReportTimeline(history,profile,range),[history,profile,range]);const exerciseOptions=useMemo(()=>{const map={};data.weeks.flatMap(w=>w.performance).forEach(e=>{map[e.id]=e.name});return Object.entries(map)},[data]);const filtered=data.weeks.map(w=>({...w,performance:exercise==='Todos'?w.performance:w.performance.filter(e=>e.id===exercise)}));const evolutionFor=key=>data.evolution[key];return <><Header title="Linha do tempo" onBack={()=>go('weeklyReport')}/><main className="page"><section className="timelineHero"><span>EVOLUÇÃO SEMANA A SEMANA</span><h2>Seu histórico de desempenho</h2><p>Compare aderência, volume, RPE, carga e desempenho por exercício ao longo do período selecionado.</p></section><div className="timelineFilters"><div><label>Período<select value={range} onChange={e=>setRange(Number(e.target.value))}><option value="4">4 semanas</option><option value="8">8 semanas</option><option value="12">12 semanas</option><option value="24">24 semanas</option><option value="52">1 ano</option></select></label></div><div><label>Exercício<select value={exercise} onChange={e=>setExercise(e.target.value)}><option value="Todos">Todos os exercícios</option>{exerciseOptions.map(([id,name])=><option value={id} key={id}>{name}</option>)}</select></label></div></div><section className="timelineMetrics"><div><span>Aderência</span><b>{evolutionFor('adherence')>0?'+':''}{evolutionFor('adherence')} pts</b><small>primeira → última semana</small></div><div><span>Volume</span><b>{evolutionFor('volume')>0?'+':''}{evolutionFor('volume')}%</b><small>primeira → última semana</small></div><div><span>Carga</span><b>{evolutionFor('load')>0?'+':''}{evolutionFor('load')}%</b><small>carga máxima</small></div><div><span>RPE</span><b>{evolutionFor('rpe')>0?'+':''}{evolutionFor('rpe')}</b><small>variação média</small></div></section><section className="timelineHighlights"><div className="reportTitle"><h3>Destaques automáticos</h3><TrendingUp size={19}/></div>{data.highlights.length?data.highlights.map(e=><div className="timelineHighlight" key={e.id}><div><b>{e.name}</b><small>{e.latest||0} kg • evolução no período</small></div><strong className={e.delta>0?'reportUp':e.delta<0?'reportDown':''}>{e.delta>0?'+':''}{e.delta}%</strong></div>):<p className="reportMuted">Registre mais treinos para gerar destaques.</p>}</section><div className="timelineList">{filtered.map((w,i)=><article className="timelineWeek" key={w.key}><div className="timelineDot"/><div className="timelineWeekHead"><div><span>SEMANA {i+1}</span><h3>{new Date(w.start).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})} — {new Date(w.end).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})}</h3></div>{w.highlights.length>0&&<strong>{w.highlights.length} destaque(s)</strong>}</div><div className="timelineStatRow"><div><b>{w.metrics.adherence}%</b><small>aderência</small></div><div><b>{w.metrics.volume?new Intl.NumberFormat('pt-BR',{maximumFractionDigits:0}).format(w.metrics.volume):'0'}</b><small>volume</small></div><div><b>{w.metrics.rpe||'—'}</b><small>RPE médio</small></div><div><b>{w.metrics.load||0} kg</b><small>carga máx.</small></div></div>{w.highlights.length>0&&<div className="weekBadges">{w.highlights.map(x=><span key={x}>{x}</span>)}</div>}{w.performance.length>0&&<div className="timelineExercises">{w.performance.slice(0,exercise==='Todos'?4:10).map(e=><div className="timelineExercise" key={e.id}><div><b>{e.name}</b><small>{e.maxLoad||0} kg • {e.avgReps||0} reps • {e.sets} séries</small></div><strong className={e.status==='melhorou'?'reportUp':e.status==='piorou'?'reportDown':''}>{e.status==='melhorou'?'↑ Melhorou':e.status==='piorou'?'↓ Piorou':'→ Estável'}</strong></div>)}</div>}{w.metrics.sessions===0&&<p className="reportMuted">Nenhum treino registrado nesta semana.</p>}</article>)}</div><button className="primary full" onClick={()=>go('coach')}><TrendingUp size={18}/> Usar dados no Coach IA</button><p className="muted analysisDisclaimer">Os destaques são calculados a partir dos registros do aplicativo. Carga e RPE devem ser interpretados em conjunto; a ACSM destaca individualização, consistência e ajuste de carga/volume ao objetivo.</p></main></>}



function Profile({profile,setProfile,go}){const [draft,setDraft]=useState({...profile,height:profile.height||'',weight:profile.weight||''});const height=Number(draft.height)||0;const weight=Number(draft.weight)||0;const bmi=height>0&&weight>0?weight/((height/100)*(height/100)):null;const bmiLabel=!bmi?'Preencha seus dados':bmi<18.5?'Abaixo do peso':bmi<25?'Faixa de referência':bmi<30?'Sobrepeso':bmi<35?'Obesidade grau I':bmi<40?'Obesidade grau II':'Obesidade grau III';const save=()=>{setProfile({...draft,height,weight,imc:bmi?Number(bmi.toFixed(1)):''});go('home')};return <><Header title="Perfil e saúde" onBack={()=>go('home')}/><main className="page"><div className="profileIcon"><User size={34}/></div><label>Nome<input value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})}/></label><label>Objetivo<select value={draft.goal} onChange={e=>setDraft({...draft,goal:e.target.value})}><option>Hipertrofia</option><option>Emagrecimento</option><option>Força</option><option>Condicionamento</option></select></label><label>Nível<select value={draft.level} onChange={e=>setDraft({...draft,level:e.target.value})}><option>Iniciante</option><option>Intermediário</option><option>Avançado</option></select></label><section className="bmiCard"><div><span>IMC</span><b>{bmi?bmi.toFixed(1):'—'}</b><small>{bmiLabel}</small></div><div className="bmiFormula">Peso ÷ altura²<br/><small>kg/m²</small></div></section><div className="formGrid"><label>Altura (cm)<input inputMode="numeric" type="number" min="100" max="250" value={draft.height} onChange={e=>setDraft({...draft,height:e.target.value})} placeholder="Ex.: 175"/></label><label>Peso (kg)<input inputMode="decimal" type="number" min="20" max="300" value={draft.weight} onChange={e=>setDraft({...draft,weight:e.target.value})} placeholder="Ex.: 75"/></label></div><p className="muted healthNote">O IMC é uma medida de triagem para adultos e não mede diretamente a composição corporal. Use o resultado como referência, não como diagnóstico.</p><button className="primary full" onClick={save}><Save/> Salvar perfil</button></main></>}

function BottomNav({active,go}){return <nav className="bottom"><button className={active==='home'?'active':''} onClick={()=>go('home')}><HomeIcon/><span>Home</span></button><button className={active==='programs'?'active':''} onClick={()=>go('programs')}><Dumbbell/><span>Programas</span></button><button className={active==='library'?'active':''} onClick={()=>go('library')}><Search/><span>Exercícios</span></button><button className={active==='custom'?'active':''} onClick={()=>go('custom')}><Save/><span>Meus treinos</span></button><button className={active==='profile'?'active':''} onClick={()=>go('profile')}><User/><span>Perfil</span></button></nav>}

export default function App(){const [screen,setScreen]=useState('home');const [selected,setSelected]=useState(programs[0]);const {history,profile,setProfile,saveWorkout,customWorkouts,saveCustomWorkout,cloud}=useWorkoutStorage();const go=(next,data)=>{if(data)setSelected(data);setScreen(next)};if(screen==='home')return <Home go={go} history={history} profile={profile} cloud={cloud}/>;if(screen==='programs')return <Programs go={go}/>;if(screen==='globalPrograms')return <GlobalPrograms go={go}/>;if(screen==='personalPlan')return <PersonalPlan go={go} profile={profile} setProfile={setProfile}/>;if(screen==='personalDetails')return <PersonalDetails go={go} plan={selected} saveCustomWorkout={saveCustomWorkout}/>;if(screen==='globalDetails')return <GlobalDetails program={selected} go={go}/>;if(screen==='library')return <Library go={go}/>;if(screen==='custom')return <CustomWorkouts go={go} customWorkouts={customWorkouts}/>;if(screen==='builder')return <Builder go={go} saveCustomWorkout={saveCustomWorkout}/>;if(screen==='customDetails')return <CustomDetails program={selected} go={go}/>;if(screen==='exercise')return <ExerciseDetails exercise={selected} go={go}/>;if(screen==='details')return <Details program={selected} go={go}/>;if(screen==='workout')return <Workout program={selected} go={go} saveWorkout={saveWorkout} history={history}/>;if(screen==='done')return <Done program={selected} go={go}/>;if(screen==='history')return <HistoryScreen history={history} go={go}/>;if(screen==='evolution')return <Evolution history={history} go={go}/>;if(screen==='analysis')return <AthleteAnalysis history={history} profile={profile} go={go}/>;if(screen==='coach')return <CoachAI history={history} profile={profile} go={go} saveCustomWorkout={saveCustomWorkout}/>;if(screen==='weeklyReport')return <WeeklyReport history={history} profile={profile} go={go}/>;if(screen==='reportTimeline')return <ReportTimeline history={history} profile={profile} go={go}/>;return <Profile profile={profile} setProfile={setProfile} go={go}/>;}